pub fn emit_to_disk(ir: &CanonIR, plan: &Plan, root: &Path) -> Result<()> {
    for (path, content) in emit(ir, plan) {
        let full = root.join(path);
        if let Some(parent) = full.parent() {
            fs::create_dir_all(parent)?;
        }
        fs::write(full, content)?;
    }
    Ok(())
}

